INSERT OR IGNORE INTO events (id, slug, title, summary, description, event_date, start_note, location, cost, publication, created_at, updated_at, published_at) VALUES
  ('evt-riverton-spring-row', 'spring-row-and-breakfast', 'Spring row and breakfast', 'A gentle morning on the river, followed by breakfast at the shed.', 'Meet at the shed while the mist is still on the water. We will take out the stable quads for a social row upstream, then come back for eggs, toast and very strong coffee. New members are welcome; an experienced cox will be in each boat.', '2026-11-14', '7:00 am for a 7:30 am start', 'Riverton Boathouse, 4 River Parade', 'Free for members; $10 for guests', 'Published', '2026-10-01T00:00:00.000Z', '2026-10-20T09:15:00.000Z', '2026-10-20T09:15:00.000Z'),
  ('evt-riverton-learn-to-row', 'learn-to-row-open-day', 'Learn to row open day', 'Try a rowing shell on flat water with a coach beside you.', 'A low-pressure introduction for adults who have never rowed. We start on the pontoon with the basics, then take the training barge out in pairs. Wear clothes you can move in and bring a water bottle. The shed has changing rooms and showers.', '2026-12-05', '8:30 am for a 9:00 am start', 'Riverton Boathouse, 4 River Parade', 'Gold coin donation', 'Published', '2026-10-02T00:00:00.000Z', '2026-10-21T03:40:00.000Z', '2026-10-21T03:40:00.000Z'),
  ('evt-riverton-twilight', 'twilight-paddle-and-supper', 'Twilight paddle and supper', 'An evening paddle for confident beginners, then soup by the river.', 'A shorter social paddle as the light goes. This one suits people who have completed one learn-to-row session. Numbers are limited so we can keep the group together. Supper is vegetarian by default; tell us about other needs when you join.', '2027-01-16', '5:30 pm for a 6:00 pm start', 'Riverton Boathouse, 4 River Parade', 'Bring a plate to share', 'Draft', '2026-10-03T00:00:00.000Z', '2026-10-22T06:05:00.000Z', NULL);

INSERT OR IGNORE INTO notices (id, title, body, notice_date, publication, created_at, updated_at, published_at) VALUES
  ('note-riverton-agm', 'Annual general meeting', 'The club’s annual general meeting is on Sunday 8 November at 10:00 am in the boat shed. We will elect the committee, review the year and approve the 2027 budget. Please bring a chair; tea and biscuits are provided.', '2026-10-20', 'Published', '2026-10-20T01:00:00.000Z', '2026-10-20T01:00:00.000Z', '2026-10-20T01:00:00.000Z'),
  ('note-riverton-shed', 'Shed working bee', 'The pontoon needs a new handrail. We are meeting on Saturday 31 October from 9:00 am with tools, paint and a plan. No building experience needed; there is a job for every pair of hands.', '2026-10-12', 'Published', '2026-10-12T02:00:00.000Z', '2026-10-12T02:00:00.000Z', '2026-10-12T02:00:00.000Z');
